@layer tema-fundo {
  html:is([data-theme="radio"], [data-theme="papel"], [data-theme="neon"], [data-theme="fliperama"], [data-theme="jardim"], [data-theme="observatorio"]) :is([data-raiz-do-app], [data-raiz-do-app] main.bg-canvas) { background-color: transparent; }
  html:is([data-theme="radio"], [data-theme="papel"], [data-theme="neon"], [data-theme="fliperama"], [data-theme="jardim"], [data-theme="observatorio"]) body::before, html:is([data-theme="radio"], [data-theme="papel"], [data-theme="neon"], [data-theme="fliperama"], [data-theme="jardim"], [data-theme="observatorio"]) body::after { content: ""; position: fixed; pointer-events: none; z-index: -1; }
  html:is([data-theme="radio"], [data-theme="papel"], [data-theme="neon"], [data-theme="fliperama"], [data-theme="jardim"], [data-theme="observatorio"]) body::before { inset: -12%; background-image: var(--fundo-animado); animation: 48s ease-in-out 0s infinite alternate none running fundo-do-tema; will-change: transform; }
  html:is([data-theme="radio"], [data-theme="papel"], [data-theme="neon"], [data-theme="fliperama"], [data-theme="jardim"], [data-theme="observatorio"]) body::after { inset: 0px; background-image: var(--textura); background-size: var(--textura-tam, auto); }
}
@keyframes fundo-do-tema { 
  0% { transform: translate3d(-3%, -2%, 0px) rotate(-2deg); }
  100% { transform: translate3d(3%, 2%, 0px) rotate(2deg); }
}
html[data-modo-leve="true"] { --fundo-animado: none !important; --textura: none !important; }
html[data-modo-leve="true"] body::before, body.performance-mode::before, body.animations-off::before { animation: auto ease 0s 1 normal none running none; display: none; }
@media (prefers-reduced-motion: reduce) {
  html:not(:has(body.animations-on)) { --fundo-animado: none !important; }
  body:not(.animations-on)::before { animation: auto ease 0s 1 normal none running none; display: none; }
}
*, ::before, ::after { box-sizing: border-box; }
html { margin: 0px; height: 100%; }
body { font: 14px/1.5 var(--font-body); color: var(--ink); -webkit-font-smoothing: antialiased; }
::selection { background: color-mix(in srgb,var(--accent) 30%,transparent); color: var(--ink); }
* { scrollbar-width: thin; scrollbar-color: var(--border-strong) transparent; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.btn:focus-visible, .pill:focus-visible, .cartao:focus-visible, .campo:focus-visible, .item:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--canvas),0 0 0 4px var(--accent); }
h1, h2, h3 { font-family: var(--font-display); margin: 0px; text-wrap: balance; }
p { margin: 0px; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
svg.lucide { flex: 0 0 auto; }
.rail { position: relative; z-index: 2; background: var(--surface); border-right: 1px solid var(--border-subtle); display: flex; flex-direction: column; min-height: 0px; }
.rail-topo { display: flex; align-items: center; justify-content: space-between; padding: 14px 14px 12px 16px; border-bottom: 1px solid var(--border-subtle); }
.marca { display: flex; align-items: center; gap: 10px; font-family: var(--font-marca); font-weight: 700; font-size: 15px; line-height: 1; white-space: nowrap; letter-spacing: 0.02em; }
.marca b { color: var(--accent-ink); font-weight: 700; }
.marca svg { width: 30px; height: 30px; }
.rail nav { padding: 10px 8px; display: flex; flex-direction: column; gap: 2px; overflow-y: auto; }
.item { position: relative; display: flex; align-items: center; gap: 12px; width: 100%; min-height: 42px; padding: 0px 12px; border: 0px; border-radius: var(--r-btn); background: none; color: var(--ink-muted); font: 700 13.5px var(--font-display); text-align: left; transition: background-color 0.18s, color 0.18s; }
.item:hover { background: var(--surface-hover); color: var(--ink); }
.item:hover svg { transform: translate(1px); }
.item[aria-current="page"] { background: var(--accent-soft); color: var(--accent-ink); box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--accent) 16%,transparent); }
.item[aria-current="page"]::before { content: ""; position: absolute; left: -8px; top: 11px; bottom: 11px; width: 3px; border-radius: 0px 3px 3px 0px; background: var(--accent); box-shadow: 0 0 8px color-mix(in srgb,var(--accent) 60%,transparent); animation: marca .3s var(--ease); }
@keyframes marca { 
  0% { transform: scaleY(0.2); opacity: 0; }
}
.item svg { width: 18px; height: 18px; transition: transform .2s var(--ease); }
.grupo-nav { padding: 14px 12px 6px; font: 700 9.5px var(--font-mono); letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-muted); }
.rail { background: linear-gradient(180deg,var(--surface) 0%,color-mix(in srgb,var(--surface) 70%,var(--canvas)) 100%); }
.rail-pe { margin-top: auto; padding: 10px; border-top: 1px solid var(--border-subtle); }
.cluster { display: flex; align-items: center; justify-content: space-between; gap: 2px; padding: 4px; border: 1px solid var(--border-subtle); border-radius: 14px; background: var(--canvas); }
.cluster { box-shadow: rgba(38, 36, 31, 0.06) 0px 1px 2px inset; }
.cluster button { width: 36px; height: 36px; border: 0px; border-radius: 10px; background: none; color: var(--ink-muted); display: grid; place-items: center; transition: background-color .18s,color .18s,transform .18s var(--ease); }
.cluster button:hover { background: var(--surface); color: var(--ink); box-shadow: rgba(38, 36, 31, 0.1) 0px 1px 3px; }
.cluster button:active { transform: scale(0.92); }
.cluster .conta { background: var(--accent-soft); color: var(--accent-ink); border-radius: 50%; }
.cluster .conta.convidado { outline: 2px dashed var(--accent); outline-offset: 1px; }
.cluster svg { width: 17px; height: 17px; }
.principal { position: relative; display: flex; flex-direction: column; min-width: 0px; min-height: 0px; }
